import java.util.Scanner;

public class Main {
    static final int maxn = 8;
    static final int SZ = 1048576 + 5;
    static final int MOD = 1000000007;

    static int n;
    static int[][] a = new int[maxn][maxn];
    static int inv100;
    static int[][] g = new int[maxn][maxn];
    static int[] p = new int[SZ];
    static int[][][] num = new int[7][7][7];
    static int all;
    static int Ans;
    static int cnt;

    static int inc(int a, int b) {
        int res = a + b;
        return res >= MOD ? res - MOD : res;
    }

    static int dec(int a, int b) {
        return a >= b ? a - b : a + MOD - b;
    }

    static int mul(int a, int b) {
        return (int) ((long) a * b % MOD);
    }

    static void updata(int x, int y) {
        // x is lvalue, but in Java we pass array and index
        // We'll use an overload for array
    }

    static void updata(int[] arr, int idx, int y) {
        arr[idx] = inc(arr[idx], y);
    }

    static int power(int x, int k) {
        long tmp = 1;
        long base = x;
        while (k > 0) {
            if ((k & 1) == 1)
                tmp = (tmp * base) % MOD;
            base = (base * base) % MOD;
            k >>= 1;
        }
        return (int) tmp;
    }

    static boolean check(int x, int y, int z) {
        int[] lis = {x, y, z};
        int[][] perms = {
            {0, 1, 2}, {0, 2, 1}, {1, 0, 2}, {1, 2, 0}, {2, 0, 1}, {2, 1, 0}
        };
        for (int[] perm : perms) {
            boolean flag = true;
            for (int i = 0; i < 3; i++) {
                if (g[perm[i] + 1][lis[i]] == 0) {
                    flag = false;
                    break;
                }
            }
            if (flag)
                return true;
        }
        return false;
    }

    static void dfs1(int now, int x, int y) {
        if (now == 0)
            return;
        if (x == 4) {
            int[] used = new int[7];
            for (int i = 1; i <= 6; i++)
                used[i] = 1;
            int sta = 0;
            for (int i = 1; i <= 6; i++) {
                for (int j = i + 1; j <= 6; j++) {
                    for (int k = j + 1; k <= 6; k++) {
                        if (check(i, j, k)) {
                            int X = -1, Y = -1, Z = -1;
                            used[i] = used[j] = used[k] = 0;
                            for (int l = 1; l <= 6; l++) {
                                if (used[l] != 0) {
                                    if (X == -1)
                                        X = l;
                                    else if (Y == -1)
                                        Y = l;
                                    else
                                        Z = l;
                                }
                            }
                            used[i] = used[j] = used[k] = 1;
                            if (Z == -1)
                                continue;
                            sta |= num[X][Y][Z];
                        }
                    }
                }
            }
            updata(p, sta, now);
            return;
        }
        g[x][y] = 1;
        int nxt = mul(now, a[x][y]);
        if (y == 6)
            dfs1(nxt, x + 1, 1);
        else
            dfs1(nxt, x, y + 1);
        g[x][y] = 0;
        nxt = mul(now, dec(1, a[x][y]));
        if (y == 6)
            dfs1(nxt, x + 1, 1);
        else
            dfs1(nxt, x, y + 1);
    }

    static void dfs2(int now, int x, int y) {
        if (now == 0)
            return;
        if (x == 7) {
            int sta = 0;
            for (int i = 1; i <= 6; i++) {
                for (int j = i + 1; j <= 6; j++) {
                    for (int k = j + 1; k <= 6; k++) {
                        if (check(i, j, k))
                            sta |= num[i][j][k];
                    }
                }
            }
            updata(Ans, mul(now, p[all ^ sta]));
            return;
        }
        g[x - 3][y] = 1;
        int nxt = mul(now, a[x][y]);
        if (y == 6)
            dfs2(nxt, x + 1, 1);
        else
            dfs2(nxt, x, y + 1);
        g[x - 3][y] = 0;
        nxt = mul(now, dec(1, a[x][y]));
        if (y == 6)
            dfs2(nxt, x + 1, 1);
        else
            dfs2(nxt, x, y + 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        inv100 = power(100, MOD - 2);
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                a[i][j] = sc.nextInt();
                a[i][j] = mul(a[i][j], inv100);
            }
        }
        for (int i = n + 1; i <= 6; i++)
            a[i][i] = 1;

        cnt = 0;
        for (int i = 1; i <= 6; i++) {
            for (int j = i + 1; j <= 6; j++) {
                for (int k = j + 1; k <= 6; k++) {
                    num[i][j][k] = 1 << cnt;
                    cnt++;
                }
            }
        }
        all = (1 << cnt) - 1;

        dfs1(1, 1, 1);

        // SOS DP
        for (int j = 0; j < cnt; j++) {
            for (int i = 0; i < (1 << cnt); i++) {
                if ((i & (1 << j)) != 0)
                    updata(p, i, p[i ^ (1 << j)]);
            }
        }

        Ans = 0;
        dfs2(1, 4, 1);
        Ans = dec(1, Ans);
        System.out.println(Ans);
        sc.close();
    }
}
